class Solution {public int[] solve(int n,int[][] edges){ArrayList<ArrayList<Integer>>a=new ArrayList<>();for(int i=0;i<n;i++)a.add(new ArrayList<>());int[] degree=new int[n];for(int[]e:edges){a.get(e[0]).add(e[1]);degree[e[1]]++;}ArrayList<Integer>q=new ArrayList<>();for(int i=0;i<n;i++)if(degree[i]==0)q.add(i);for(int i=0;i<q.size();i++)for(int v:a.get(q.get(i)))if(--degree[v]==0)q.add(v);if(q.size()!=n)return new int[0];return q.stream().mapToInt(Integer::intValue).toArray();}}